#include <iostream>
#include <string>

class GeometricObject {
public:
    virtual ~GeometricObject() = default;
    virtual std::string toString() const {
        return "Geometric object";
    }
};

class Circle : public GeometricObject {
public:
    std::string toString() const override {
        return "Circle object";
    }
};

class Rectangle : public GeometricObject {
public:
    std::string toString() const override {
        return "Rectangle object";
    }
};

// Dynamic binding via reference
void displayByReference(const GeometricObject& g) {
    std::cout << g.toString() << "\n";
}

// Object slicing via pass-by-value
void displayByValue(GeometricObject g) {
    std::cout << g.toString() << "\n";
}

int main() {
    GeometricObject shape;
    Circle circle;
    Rectangle rectangle;

    std::cout << "--- Dynamic Binding (Reference) ---\n";
    displayByReference(shape);
    displayByReference(circle);
    displayByReference(rectangle);

    std::cout << "--- Object Slicing (Value) ---\n";
    displayByValue(shape);
    displayByValue(circle);
    displayByValue(rectangle);

    return 0;
}
